/* ==========================================================================
   RENT RIDE · INTERNATIONAL AUTOMOTIVE ATELIER
   Luxury Dark-Mode Design System & Layout Styles
   ========================================================================== */

:root {
  /* Core Obsidian Palette */
  --bg-obsidian: #080705;
  --bg-onyx: #0d0b07;
  --bg-card: #12100b;
  --bg-card-elevated: #17140e;
  --bg-studio: #0e0c08;

  /* Champagne & Antique Gold Accents */
  --gold-primary: #d4af37;
  --gold-antique: #c8a237;
  --gold-bright: #e8cb6b;
  --gold-soft: rgba(212, 175, 55, 0.14);
  --gold-border: rgba(212, 175, 55, 0.2);
  --gold-border-strong: rgba(212, 175, 55, 0.45);

  /* Typography Colors */
  --text-primary: #f6f2e9;
  --text-secondary: #b6ae9f;
  --text-muted: #847c6e;

  /* Status Colors */
  --status-green: #4ade80;
  --status-green-bg: rgba(74, 222, 128, 0.12);
  --status-green-border: rgba(74, 222, 128, 0.32);

  /* Typography Families */
  --font-serif: "Cormorant Garamond", Georgia, serif;
  --font-sans: "Plus Jakarta Sans", "Inter", -apple-system, BlinkMacSystemFont, sans-serif;

  /* Radii & Shadows */
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-pill: 999px;
  --shadow-card: 0 20px 50px rgba(0, 0, 0, 0.55);
  --shadow-gold-glow: 0 0 32px rgba(212, 175, 55, 0.12);

  /* Layout */
  --container-max: 1360px;
  --header-height: 78px;
  --transition-fast: 180ms cubic-bezier(0.22, 1, 0.36, 1);
  --transition-smooth: 320ms cubic-bezier(0.22, 1, 0.36, 1);
}

/* ==========================================================================
   RESET & BASE
   ========================================================================== */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  background-color: var(--bg-obsidian);
  color: var(--text-primary);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(circle at 50% -10%, rgba(212, 175, 55, 0.08), transparent 48%),
    linear-gradient(180deg, var(--bg-obsidian) 0%, var(--bg-onyx) 45%, var(--bg-obsidian) 100%);
  color: var(--text-primary);
  overflow-x: hidden;
}

.ambient-backdrop {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: -1;
  background:
    radial-gradient(ellipse 70% 40% at 50% 0%, rgba(212, 175, 55, 0.055), transparent 70%);
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  color: inherit;
  background: none;
  border: none;
  cursor: pointer;
}

img {
  display: block;
  max-width: 100%;
}

.tabular {
  font-variant-numeric: tabular-nums;
}

.container {
  width: min(var(--container-max), calc(100% - 48px));
  margin-inline: auto;
}

/* ==========================================================================
   STICKY TOP NAVIGATION BAR
   ========================================================================== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 60;
  height: var(--header-height);
  background: rgba(8, 7, 5, 0.86);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border-bottom: 1px solid var(--gold-border);
}

.header-inner {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

/* Brand Lockup */
.brand-lockup {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}

.brand-monogram {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border: 1px solid var(--gold-primary);
  border-radius: 6px;
  background: linear-gradient(145deg, rgba(212, 175, 55, 0.16), rgba(212, 175, 55, 0.03));
  font-family: var(--font-serif);
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--gold-bright);
  box-shadow: inset 0 0 12px rgba(212, 175, 55, 0.14);
}

.brand-text {
  display: flex;
  flex-direction: column;
  line-height: 1.1;
}

.brand-title {
  font-family: var(--font-serif);
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--text-primary);
}

.brand-subtitle {
  font-size: 0.62rem;
  font-weight: 600;
  letter-spacing: 0.24em;
  color: var(--gold-primary);
  margin-top: 2px;
}

/* Center Nav Links */
.main-nav {
  display: flex;
  align-items: center;
  gap: 26px;
}

.nav-link {
  position: relative;
  padding: 8px 2px;
  font-size: 0.84rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.nav-link:hover,
.nav-link.is-active {
  color: var(--text-primary);
}

.nav-link.is-active::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -2px;
  height: 2px;
  background: linear-gradient(90deg, var(--gold-antique), var(--gold-bright));
  border-radius: 2px;
  box-shadow: 0 0 10px rgba(212, 175, 55, 0.5);
}

/* Right Header Controls */
.header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.icon-svg {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
}

.pill-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 38px;
  padding: 0 14px;
  border-radius: var(--radius-pill);
  font-size: 0.78rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.pill-btn-outline {
  border: 1px solid var(--gold-border);
  background: rgba(18, 16, 11, 0.8);
  color: var(--text-primary);
}

.pill-btn-outline:hover {
  border-color: var(--gold-border-strong);
  background: rgba(212, 175, 55, 0.09);
}

.pill-btn-outline .icon-svg {
  color: var(--gold-primary);
}

.cta-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  height: 38px;
  padding: 0 18px;
  border-radius: var(--radius-pill);
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.cta-btn-gold {
  background: linear-gradient(135deg, var(--gold-bright) 0%, var(--gold-primary) 55%, var(--gold-antique) 100%);
  color: #0b0905;
  box-shadow: 0 6px 22px rgba(212, 175, 55, 0.24);
}

.cta-btn-gold:hover {
  transform: translateY(-1px);
  box-shadow: 0 10px 28px rgba(212, 175, 55, 0.36);
  filter: brightness(1.04);
}

.cta-btn-outline {
  border: 1px solid var(--gold-border-strong);
  background: rgba(18, 16, 11, 0.65);
  color: var(--text-primary);
}

.cta-btn-outline:hover {
  border-color: var(--gold-primary);
  background: rgba(212, 175, 55, 0.1);
}

.cta-btn-lg {
  height: 46px;
  padding: 0 26px;
  font-size: 0.78rem;
}

.cta-btn-full {
  width: 100%;
  height: 46px;
}

/* Mobile Menu Button & Drawer */
.mobile-menu-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 38px;
  height: 38px;
  padding: 0 9px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--gold-border);
}

.mobile-menu-toggle span {
  display: block;
  height: 1.5px;
  width: 100%;
  background: var(--gold-primary);
}

.mobile-drawer {
  position: absolute;
  top: var(--header-height);
  left: 0;
  right: 0;
  background: rgba(10, 9, 6, 0.98);
  border-bottom: 1px solid var(--gold-border);
  padding: 20px 24px 24px;
}

.mobile-nav {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 18px;
}

.mobile-nav-link {
  font-size: 0.95rem;
  color: var(--text-secondary);
  padding: 6px 0;
}

.mobile-nav-link.is-active {
  color: var(--gold-bright);
}

.mobile-drawer-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

/* ==========================================================================
   1. HERO SECTION
   ========================================================================== */
.hero-section {
  padding: 64px 0 42px;
  text-align: center;
}

.hero-container {
  max-width: 900px;
}

.hero-kicker {
  margin: 0 0 18px;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--gold-primary);
}

.hero-title {
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
  font-family: var(--font-serif);
  font-size: clamp(2.7rem, 6vw, 4.9rem);
  font-weight: 600;
  line-height: 0.98;
  letter-spacing: 0.04em;
}

.hero-title-line {
  display: block;
  color: var(--text-primary);
}

.hero-title-gold {
  background: linear-gradient(135deg, #f3dc8a 0%, var(--gold-primary) 50%, #b78d24 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.hero-subtitle {
  margin: 22px auto 30px;
  max-width: 680px;
  font-size: 1.02rem;
  line-height: 1.65;
  color: var(--text-secondary);
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 14px;
}

/* ==========================================================================
   2. INTERACTIVE VAULT ARRIVAL STAGE
   ========================================================================== */
.vault-section {
  padding: 12px 0 34px;
}

.vault-card {
  border-radius: var(--radius-lg);
  border: 1px solid var(--gold-border);
  background:
    radial-gradient(circle at 50% 45%, rgba(212, 175, 55, 0.09), transparent 65%),
    linear-gradient(180deg, #110f0b 0%, #090806 100%);
  box-shadow: var(--shadow-card), var(--shadow-gold-glow);
  overflow: hidden;
}

.vault-header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 16px 24px;
  border-bottom: 1px solid var(--gold-border);
  background: rgba(18, 15, 10, 0.72);
}

.vault-header-left {
  display: flex;
  align-items: center;
  gap: 10px;
}

.vault-live-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gold-primary);
  box-shadow: 0 0 12px var(--gold-primary);
}

.vault-header-title {
  font-size: 0.74rem;
  font-weight: 600;
  letter-spacing: 0.22em;
  color: var(--text-primary);
}

.vault-header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.stage-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 34px;
  padding: 0 14px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--gold-border);
  background: rgba(12, 10, 7, 0.85);
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.stage-btn:hover {
  border-color: var(--gold-border-strong);
  color: var(--text-primary);
}

.stage-btn-gold {
  border-color: rgba(212, 175, 55, 0.4);
  background: rgba(212, 175, 55, 0.12);
  color: var(--gold-bright);
}

.stage-btn-gold:hover {
  background: rgba(212, 175, 55, 0.22);
  color: var(--gold-bright);
}

/* Stage Canvas & Animations */
.vault-stage-canvas {
  position: relative;
  padding: 18px 24px 22px;
}

.vault-stage-hud {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-bottom: 6px;
}

.hud-chip {
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  color: var(--gold-primary);
  padding: 5px 11px;
  border-radius: var(--radius-pill);
  border: 1px solid rgba(212, 175, 55, 0.22);
  background: rgba(212, 175, 55, 0.06);
}

.hud-chip-muted {
  color: var(--text-muted);
  border-color: rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.02);
}

.vault-scene-svg {
  width: 100%;
  max-height: 340px;
  display: block;
}

.vault-door-left,
.vault-door-right {
  transition: transform 650ms cubic-bezier(0.22, 1, 0.36, 1), opacity 500ms ease;
}

.vault-card[data-vault-revealed="true"] .vault-door-left {
  transform: translateX(-165px);
  opacity: 0.18;
}

.vault-card[data-vault-revealed="true"] .vault-door-right {
  transform: translateX(165px);
  opacity: 0.18;
}

.vault-car-group {
  transform-origin: center;
}

.vault-card.is-replaying .vault-car-group {
  animation: carArrivalGlide 1.45s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.vault-card.is-replaying .car-draw-path {
  stroke-dasharray: 1400;
  stroke-dashoffset: 1400;
  animation: drawGoldLine 1.5s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

@keyframes carArrivalGlide {
  0% {
    opacity: 0;
    transform: translateX(-110px) scale(0.95);
  }
  100% {
    opacity: 1;
    transform: translateX(0) scale(1);
  }
}

@keyframes drawGoldLine {
  to {
    stroke-dashoffset: 0;
  }
}

/* Vault Reveal Panel */
.vault-reveal-panel {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr)) auto;
  align-items: center;
  gap: 16px;
  max-height: 0;
  opacity: 0;
  overflow: hidden;
  padding: 0 4px;
  margin-top: 0;
  border-top: 0 solid var(--gold-border);
  transition: all 380ms cubic-bezier(0.22, 1, 0.36, 1);
}

.vault-card[data-vault-revealed="true"] .vault-reveal-panel {
  max-height: 140px;
  opacity: 1;
  padding-top: 18px;
  margin-top: 10px;
  border-top-width: 1px;
}

.vault-reveal-label {
  display: block;
  font-size: 0.65rem;
  letter-spacing: 0.18em;
  color: var(--text-muted);
  margin-bottom: 4px;
}

.vault-reveal-value {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text-primary);
  letter-spacing: 0.04em;
}

/* ==========================================================================
   3. KPI / STAT STRIP
   ========================================================================== */
.kpi-section {
  padding: 10px 0 44px;
}

.kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
}

.kpi-card {
  padding: 22px 24px;
  border-radius: var(--radius-md);
  border: 1px solid var(--gold-border);
  background: linear-gradient(180deg, rgba(22, 19, 13, 0.92) 0%, rgba(13, 11, 7, 0.96) 100%);
  transition: border-color var(--transition-fast), transform var(--transition-fast);
}

.kpi-card:hover {
  border-color: var(--gold-border-strong);
  transform: translateY(-2px);
}

.kpi-value {
  margin: 0 0 6px;
  font-family: var(--font-serif);
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: var(--text-primary);
}

.kpi-star {
  color: var(--gold-primary);
  font-size: 1.55rem;
}

.kpi-label {
  margin: 0;
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.2em;
  color: var(--text-muted);
}

/* ==========================================================================
   4. VEHICLE CAROUSEL SECTIONS
   ========================================================================== */
.carousel-section {
  padding: 26px 0 38px;
}

.carousel-section-last {
  padding-bottom: 72px;
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 22px;
}

.section-kicker {
  margin: 0 0 6px;
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--gold-primary);
}

.section-title {
  margin: 0;
  font-family: var(--font-serif);
  font-size: clamp(1.65rem, 2.5vw, 2.2rem);
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--text-primary);
}

.section-controls {
  display: flex;
  align-items: center;
  gap: 16px;
}

.section-link-btn {
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  color: var(--gold-bright);
  padding: 6px 2px;
  border-bottom: 1px solid rgba(212, 175, 55, 0.35);
  transition: color var(--transition-fast), border-color var(--transition-fast);
}

.section-link-btn:hover {
  color: #fff2c2;
  border-color: var(--gold-bright);
}

.session-sync-note {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.74rem;
  color: var(--text-secondary);
  padding: 6px 12px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--gold-border);
  background: rgba(18, 16, 11, 0.7);
}

.sync-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--status-green);
  box-shadow: 0 0 8px rgba(74, 222, 128, 0.65);
}

.carousel-arrows {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.arrow-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px solid var(--gold-border);
  background: var(--bg-card);
  color: var(--text-primary);
  font-size: 1.2rem;
  line-height: 1;
  display: grid;
  place-items: center;
  transition: all var(--transition-fast);
}

.arrow-btn:hover {
  border-color: var(--gold-primary);
  color: var(--gold-bright);
  background: rgba(212, 175, 55, 0.12);
}

/* Carousel Track (Horizontal Scroll + Snap) */
.carousel-track {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  padding-bottom: 10px;
  scrollbar-width: thin;
  scrollbar-color: rgba(212, 175, 55, 0.35) transparent;
}

.carousel-track.is-expanded-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(310px, 1fr));
  overflow-x: visible;
}

.carousel-track::-webkit-scrollbar {
  height: 5px;
}

.carousel-track::-webkit-scrollbar-track {
  background: rgba(255, 255, 255, 0.03);
  border-radius: 999px;
}

.carousel-track::-webkit-scrollbar-thumb {
  background: rgba(212, 175, 55, 0.3);
  border-radius: 999px;
}

/* ==========================================================================
   VEHICLE CARD & STUDIO IMAGE PLACEHOLDER
   ========================================================================== */
.vehicle-card {
  flex: 0 0 340px;
  scroll-snap-align: start;
  display: flex;
  flex-direction: column;
  border-radius: var(--radius-md);
  border: 1px solid var(--gold-border);
  background: linear-gradient(180deg, var(--bg-card-elevated) 0%, var(--bg-card) 100%);
  overflow: hidden;
  transition: transform var(--transition-smooth), border-color var(--transition-fast), box-shadow var(--transition-smooth);
}

.carousel-track.is-expanded-grid .vehicle-card {
  flex: initial;
}

.vehicle-card:hover {
  transform: translateY(-4px);
  border-color: var(--gold-border-strong);
  box-shadow: 0 22px 44px rgba(0, 0, 0, 0.6), 0 0 28px rgba(212, 175, 55, 0.08);
}

/* Media Container */
.card-media {
  position: relative;
  height: 214px;
  border-bottom: 1px solid rgba(212, 175, 55, 0.14);
  background: var(--bg-studio);
  overflow: hidden;
}

/* Styled Car Image Placeholder (Replace via imageUrl in script.js) */
.car-image-placeholder {
  position: relative;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 20px;
  text-align: center;
  background:
    radial-gradient(ellipse 75% 48% at 50% 42%, rgba(212, 175, 55, 0.14) 0%, rgba(212, 175, 55, 0.03) 55%, transparent 80%),
    linear-gradient(180deg, #17140d 0%, #0b0906 72%, #13100a 100%);
  cursor: pointer;
}

/* Subtle studio floor horizon & corner brackets */
.car-image-placeholder::before {
  content: "";
  position: absolute;
  inset: 14px;
  border: 1px dashed rgba(212, 175, 55, 0.16);
  border-radius: 8px;
  pointer-events: none;
}

.car-image-placeholder::after {
  content: "";
  position: absolute;
  left: 12%;
  right: 12%;
  bottom: 36px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(212, 175, 55, 0.35), transparent);
  pointer-events: none;
}

.placeholder-icon {
  width: 46px;
  height: 24px;
  color: rgba(212, 175, 55, 0.68);
}

.placeholder-label {
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--gold-bright);
  opacity: 0.9;
}

.placeholder-slot-hint {
  font-size: 0.64rem;
  color: var(--text-muted);
  letter-spacing: 0.04em;
}

.car-photo-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  cursor: pointer;
}

/* Card Overlay Badges */
.card-overlay-top {
  position: absolute;
  top: 12px;
  left: 12px;
  right: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  pointer-events: none;
}

.studio-tag {
  padding: 5px 10px;
  border-radius: var(--radius-pill);
  background: rgba(8, 7, 5, 0.78);
  border: 1px solid rgba(255, 255, 255, 0.12);
  backdrop-filter: blur(8px);
  font-size: 0.6rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  color: var(--text-secondary);
}

.favorite-btn {
  pointer-events: auto;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: rgba(8, 7, 5, 0.8);
  border: 1px solid rgba(212, 175, 55, 0.26);
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.favorite-btn svg {
  width: 15px;
  height: 15px;
}

.favorite-btn:hover {
  border-color: var(--gold-primary);
  color: var(--gold-bright);
}

.favorite-btn.is-favorited {
  background: rgba(212, 175, 55, 0.22);
  border-color: var(--gold-primary);
  color: var(--gold-bright);
  box-shadow: 0 0 14px rgba(212, 175, 55, 0.3);
}

.favorite-btn.is-favorited svg {
  fill: currentColor;
}

.card-overlay-bottom {
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  pointer-events: none;
}

.perk-badge {
  padding: 4px 9px;
  border-radius: var(--radius-pill);
  background: linear-gradient(135deg, rgba(212, 175, 55, 0.94), rgba(188, 146, 36, 0.94));
  color: #0b0905;
  font-size: 0.56rem;
  font-weight: 700;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 72%;
}

.spec-badge {
  padding: 4px 8px;
  border-radius: var(--radius-pill);
  background: rgba(8, 7, 5, 0.84);
  border: 1px solid rgba(212, 175, 55, 0.28);
  font-size: 0.58rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  color: var(--gold-bright);
  white-space: nowrap;
}

/* Card Body */
.card-body {
  display: flex;
  flex-direction: column;
  flex: 1;
  padding: 16px 18px 18px;
}

.card-meta-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 8px;
}

.category-kicker {
  font-size: 0.62rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--gold-primary);
}

.rating-badge {
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--text-primary);
}

.rating-badge .star {
  color: var(--gold-primary);
}

.rating-count {
  color: var(--text-muted);
  font-weight: 400;
}

.vehicle-title {
  margin: 0 0 12px;
  font-family: var(--font-serif);
  font-size: 1.24rem;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: 0.02em;
  color: var(--text-primary);
  min-height: 2.95rem;
  cursor: pointer;
}

.vehicle-title:hover {
  color: var(--gold-bright);
}

.specs-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 7px;
  margin-bottom: 16px;
}

.spec-pill {
  padding: 4px 9px;
  border-radius: var(--radius-pill);
  border: 1px solid rgba(255, 255, 255, 0.09);
  background: rgba(255, 255, 255, 0.03);
  font-size: 0.68rem;
  font-weight: 500;
  color: var(--text-secondary);
}

.status-pill-available {
  margin-left: auto;
  padding: 4px 9px;
  border-radius: var(--radius-pill);
  background: var(--status-green-bg);
  border: 1px solid var(--status-green-border);
  color: var(--status-green);
  font-size: 0.66rem;
  font-weight: 600;
}

/* Card Footer */
.card-footer {
  margin-top: auto;
  padding-top: 14px;
  border-top: 1px solid rgba(212, 175, 55, 0.14);
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
}

.price-label {
  display: block;
  font-size: 0.58rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  color: var(--text-muted);
  margin-bottom: 3px;
}

.price-value {
  font-family: var(--font-serif);
  font-size: 1.42rem;
  font-weight: 700;
  color: var(--gold-bright);
  line-height: 1;
}

.price-unit {
  font-family: var(--font-sans);
  font-size: 0.72rem;
  font-weight: 500;
  color: var(--text-secondary);
}

.reserve-card-btn {
  height: 36px;
  padding: 0 18px;
  border-radius: var(--radius-pill);
  background: linear-gradient(135deg, var(--gold-bright) 0%, var(--gold-primary) 100%);
  color: #0b0905;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  transition: all var(--transition-fast);
}

.reserve-card-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 6px 18px rgba(212, 175, 55, 0.34);
}

/* ==========================================================================
   5. FOOTER
   ========================================================================== */
.site-footer {
  border-top: 1px solid var(--gold-border);
  background: linear-gradient(180deg, #0b0906 0%, #060503 100%);
  padding: 58px 0 92px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.45fr repeat(3, minmax(0, 1fr));
  gap: 40px;
  padding-bottom: 42px;
  border-bottom: 1px solid rgba(212, 175, 55, 0.14);
}

.footer-brand-lockup {
  margin-bottom: 18px;
}

.footer-description {
  margin: 0 0 20px;
  max-width: 360px;
  font-size: 0.86rem;
  line-height: 1.65;
  color: var(--text-secondary);
}

.footer-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.footer-pill {
  padding: 6px 12px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--gold-border);
  background: rgba(18, 16, 11, 0.8);
  font-size: 0.72rem;
  color: var(--text-secondary);
}

.footer-pill-gold {
  border-color: rgba(212, 175, 55, 0.36);
  color: var(--gold-bright);
}

.footer-col-title {
  margin: 0 0 16px;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--gold-primary);
}

.footer-links {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-links a {
  font-size: 0.82rem;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.footer-links a:hover {
  color: var(--gold-bright);
}

.footer-bottom {
  padding-top: 24px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.footer-status {
  margin: 0;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-size: 0.78rem;
  color: var(--text-secondary);
}

.footer-cities {
  margin: 0;
  font-size: 0.76rem;
  letter-spacing: 0.12em;
  color: var(--text-muted);
}

/* ==========================================================================
   FLOATING BOTTOM-LEFT 18-PAGE NAVIGATOR PILL
   ========================================================================== */
.floating-navigator-pill {
  position: fixed;
  left: 22px;
  bottom: 22px;
  z-index: 70;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  height: 42px;
  padding: 0 14px 0 16px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--gold-border-strong);
  background: rgba(12, 10, 7, 0.92);
  backdrop-filter: blur(14px);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.65), 0 0 18px rgba(212, 175, 55, 0.14);
  transition: transform var(--transition-fast), border-color var(--transition-fast);
}

.floating-navigator-pill:hover {
  transform: translateY(-2px);
  border-color: var(--gold-bright);
}

.nav-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gold-primary);
  box-shadow: 0 0 10px var(--gold-primary);
}

.nav-pill-text {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--text-primary);
}

.nav-pill-badge {
  padding: 3px 8px;
  border-radius: var(--radius-pill);
  background: rgba(212, 175, 55, 0.16);
  border: 1px solid rgba(212, 175, 55, 0.35);
  font-size: 0.68rem;
  font-weight: 700;
  color: var(--gold-bright);
}

/* ==========================================================================
   MODALS & TOAST
   ========================================================================== */
.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 90;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(4, 3, 2, 0.78);
  backdrop-filter: blur(10px);
}

.modal-backdrop[hidden] {
  display: none;
}

.modal-panel {
  width: min(560px, 100%);
  max-height: 86vh;
  overflow-y: auto;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gold-border-strong);
  background: linear-gradient(180deg, #16130d 0%, #0b0906 100%);
  padding: 26px;
  box-shadow: 0 28px 70px rgba(0, 0, 0, 0.8);
}

.modal-panel-wide {
  width: min(860px, 100%);
}

.modal-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 22px;
}

.modal-kicker {
  margin: 0 0 4px;
  font-size: 0.66rem;
  font-weight: 600;
  letter-spacing: 0.2em;
  color: var(--gold-primary);
}

.modal-title {
  margin: 0;
  font-family: var(--font-serif);
  font-size: 1.7rem;
  font-weight: 600;
  color: var(--text-primary);
}

.modal-close {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1px solid var(--gold-border);
  color: var(--text-secondary);
  display: grid;
  place-items: center;
}

.modal-close:hover {
  border-color: var(--gold-primary);
  color: var(--gold-bright);
}

.navigator-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.navigator-module-card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  padding: 12px 14px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--gold-border);
  background: rgba(18, 16, 11, 0.75);
  text-align: left;
  transition: all var(--transition-fast);
}

.navigator-module-card:hover,
.navigator-module-card.is-current {
  border-color: var(--gold-primary);
  background: rgba(212, 175, 55, 0.12);
}

.module-num {
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--gold-primary);
}

.module-name {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text-primary);
}

/* Reserve Form */
.reserve-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.form-grid-2 {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.form-row {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.form-label {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-secondary);
}

.form-control {
  height: 42px;
  padding: 0 12px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--gold-border);
  background: #0a0906;
  color: var(--text-primary);
  font-family: inherit;
  font-size: 0.86rem;
}

.form-control:focus {
  outline: none;
  border-color: var(--gold-primary);
}

.form-checkbox {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.84rem;
  color: var(--text-secondary);
  cursor: pointer;
}

.form-checkbox input {
  accent-color: var(--gold-primary);
}

.reserve-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 16px;
  border-radius: var(--radius-md);
  border: 1px solid var(--gold-border);
  background: rgba(212, 175, 55, 0.06);
}

.summary-label {
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  color: var(--gold-primary);
}

.summary-sub {
  margin: 3px 0 0;
  font-size: 0.74rem;
  color: var(--text-muted);
}

.summary-price {
  font-family: var(--font-serif);
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--gold-bright);
}

/* Toast */
.toast {
  position: fixed;
  right: 22px;
  bottom: 22px;
  z-index: 100;
  max-width: 360px;
  padding: 13px 18px;
  border-radius: var(--radius-md);
  border: 1px solid var(--gold-border-strong);
  background: rgba(16, 13, 8, 0.96);
  color: var(--text-primary);
  font-size: 0.82rem;
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.7);
}

/* ==========================================================================
   RESPONSIVE BREAKPOINTS
   ========================================================================== */
@media (max-width: 1120px) {
  .main-nav {
    display: none;
  }

  .member-pill {
    display: none;
  }

  .mobile-menu-toggle {
    display: flex;
  }

  .kpi-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .footer-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .vault-card[data-vault-revealed="true"] .vault-reveal-panel {
    grid-template-columns: 1fr 1fr;
    max-height: 240px;
  }
}

@media (max-width: 720px) {
  .container {
    width: calc(100% - 32px);
  }

  #openNavigatorTop,
  #headerReserveBtn {
    display: none;
  }

  .hero-section {
    padding-top: 42px;
  }

  .vault-header {
    padding: 14px 16px;
  }

  .vault-stage-canvas {
    padding: 14px 16px 18px;
  }

  .vault-stage-hud {
    flex-direction: column;
    align-items: flex-start;
  }

  .vault-card[data-vault-revealed="true"] .vault-reveal-panel {
    grid-template-columns: 1fr;
    max-height: 320px;
  }

  .kpi-grid {
    grid-template-columns: 1fr;
  }

  .section-header {
    flex-direction: column;
    align-items: flex-start;
  }

  .vehicle-card {
    flex: 0 0 295px;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 28px;
  }

  .navigator-grid,
  .form-grid-2 {
    grid-template-columns: 1fr;
  }

  .floating-navigator-pill {
    left: 14px;
    bottom: 14px;
  }
}

