   ========================================================================== */
function formatCurrency(amount) {
  return "$" + Number(amount).toLocaleString("en-US");
}

function showToast(message) {
  const toast = document.getElementById("atelierToast");
  if (!toast) return;
  toast.textContent = message;
  toast.hidden = false;
  clearTimeout(showToast._timer);
  showToast._timer = setTimeout(() => {
    toast.hidden = true;
  }, 3200);
}

/**
 * Renders either the styled placeholder box (when imageUrl is empty)
 * or a real vehicle <img> once you add an image path in VEHICLE_CATALOG.
 */
function renderVehicleMedia(vehicle) {
  if (vehicle.imageUrl && vehicle.imageUrl.trim() !== "") {
    return `<img class="car-photo-img" src="${vehicle.imageUrl}" alt="${vehicle.title}" loading="lazy" />`;
  }

  return `
    <div class="car-image-placeholder" data-slot="${vehicle.slot}">
      <svg class="placeholder-icon" viewBox="0 0 64 28" fill="none" aria-hidden="true">
        <path d="M5 20C7 14 14 11 22 10L30 5C37 3 47 4 54 9L59 14C61 15 62 17 61 20H53M19 20H5" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/>
        <circle cx="15" cy="21" r="4" stroke="currentColor" stroke-width="1.6"/>
        <circle cx="49" cy="21" r="4" stroke="currentColor" stroke-width="1.6"/>
      </svg>
      <span class="placeholder-label">CAR IMAGE PLACEHOLDER — ADD PHOTO</span>
      <span class="placeholder-slot-hint">${vehicle.slot}</span>
    </div>
  `;
}

function createVehicleCardHTML(vehicle) {
  const isFav = appState.favorites.has(vehicle.id);

  return `
    <article class="vehicle-card" data-vehicle-id="${vehicle.id}">
      <div class="card-media">
        ${renderVehicleMedia(vehicle)}

        <div class="card-overlay-top">
          <span class="studio-tag">${vehicle.studioTag}</span>
          <button
            type="button"
            class="favorite-btn ${isFav ? "is-favorited" : ""}"
            data-favorite-id="${vehicle.id}"
            aria-label="Save ${vehicle.title} to Obsidian Garage"
            aria-pressed="${isFav}"
          >
            <svg viewBox="0 0 20 20" fill="none" aria-hidden="true">
              <path d="M10 17.25C10 17.25 3 12.6 3 7.35C3 5.1 4.75 3.35 6.95 3.35C8.28 3.35 9.45 4.02 10 5.05C10.55 4.02 11.72 3.35 13.05 3.35C15.25 3.35 17 5.1 17 7.35C17 12.6 10 17.25 10 17.25Z" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/>
            </svg>
          </button>
        </div>

        <div class="card-overlay-bottom">
          <span class="perk-badge">${vehicle.perkBadge}</span>
          <span class="spec-badge tabular">${vehicle.specYear}</span>
        </div>
      </div>

      <div class="card-body">
        <div class="card-meta-top">
          <span class="category-kicker">${vehicle.category}</span>
          <span class="rating-badge tabular">
            <span class="star">★</span> ${vehicle.rating}
            <span class="rating-count">(${vehicle.reviews})</span>
          </span>
        </div>

        <h3 class="vehicle-title" data-inspect-id="${vehicle.id}">${vehicle.title}</h3>

        <div class="specs-row">
          <span class="spec-pill">${vehicle.location}</span>
          <span class="spec-pill tabular">${vehicle.power}</span>
          <span class="status-pill-available">${vehicle.status}</span>
        </div>

        <div class="card-footer">
          <div>
            <span class="price-label">DAILY PRIVILEGE</span>
            <span class="price-value tabular">${formatCurrency(vehicle.dailyPrice)} <span class="price-unit">/day</span></span>
          </div>
          <button type="button" class="reserve-card-btn" data-reserve-id="${vehicle.id}">
            RESERVE
          </button>
        </div>
      </div>
    </article>
  `;
}

function renderAllCarousels() {
  const recommendedList = appState.showAllRecommended
    ? VEHICLE_CATALOG
    : VEHICLE_CATALOG.filter((v) => v.sections.includes("recommended")).slice(0, 5);

  const popularList = VEHICLE_CATALOG.filter((v) => v.sections.includes("popular"));
  const dealsList = VEHICLE_CATALOG.filter((v) => v.sections.includes("deals"));
  const recentList = appState.recentlyViewedIds
    .map((id) => VEHICLE_CATALOG.find((v) => v.id === id))
    .filter(Boolean);

  const tracks = [
    { id: "track-recommended", items: recommendedList },
    { id: "track-popular", items: popularList },
    { id: "track-deals", items: dealsList },
    { id: "track-recent", items: recentList },
  ];

  tracks.forEach(({ id, items }) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.innerHTML = items.map(createVehicleCardHTML).join("");
  });
}

/* ==========================================================================
   VAULT ARRIVAL INTERACTIVITY
   ========================================================================== */
function setupVaultStage() {
  const vaultCard = document.getElementById("vaultCard");
  const replayBtn = document.getElementById("replayArrivalBtn");
  const revealBtn = document.getElementById("revealVaultBtn");
  const revealLabel = document.getElementById("revealVaultLabel");
  const readout = document.getElementById("vaultStatusReadout");

  if (!vaultCard || !replayBtn || !revealBtn) return;

  function triggerArrivalAnimation() {
    vaultCard.classList.remove("is-replaying");
    void vaultCard.offsetWidth; // Force reflow so animation replays cleanly
    vaultCard.classList.add("is-replaying");
    if (readout) readout.textContent = "ARRIVAL SEQUENCE IN PROGRESS...";
    clearTimeout(triggerArrivalAnimation._timer);
    triggerArrivalAnimation._timer = setTimeout(() => {
      if (readout) readout.textContent = "ARRIVAL SEQUENCE COMPLETE";
    }, 1500);
  }

  // Run subtle entrance arrival on initial load
  triggerArrivalAnimation();

  replayBtn.addEventListener("click", () => {
    triggerArrivalAnimation();
    showToast("Replaying private vault arrival sequence.");
  });

  revealBtn.addEventListener("click", () => {
    const isRevealed = vaultCard.getAttribute("data-vault-revealed") === "true";
    const nextState = !isRevealed;
    vaultCard.setAttribute("data-vault-revealed", String(nextState));
    revealBtn.setAttribute("aria-expanded", String(nextState));
    if (revealLabel) {
      revealLabel.textContent = nextState ? "Conceal Vault ↑" : "Reveal Vault ↓";
    }
    if (readout) {
      readout.textContent = nextState ? "VAULT BAY ILLUMINATED · DOORS OPEN" : "ARRIVAL SEQUENCE COMPLETE";
    }
  });
}

/* ==========================================================================
   CAROUSELS, FAVORITES & RECENTLY VIEWED SYNC
   ========================================================================== */
function recordRecentlyViewed(vehicleId) {
  appState.recentlyViewedIds = [
    vehicleId,
    ...appState.recentlyViewedIds.filter((id) => id !== vehicleId),
  ].slice(0, 6);
  renderAllCarousels();
}

function setupCarouselsAndCards() {
  // Horizontal arrow scroll buttons
  document.querySelectorAll("[data-carousel-prev], [data-carousel-next]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const targetId = btn.getAttribute("data-carousel-prev") || btn.getAttribute("data-carousel-next");
      const track = document.getElementById(targetId);
      if (!track) return;
      const direction = btn.hasAttribute("data-carousel-prev") ? -1 : 1;
      track.scrollBy({ left: direction * 360, behavior: "smooth" });
    });
  });

  // Explore All 8 Vehicles toggle
  const exploreAllBtn = document.getElementById("exploreAllBtn");
  const recommendedTrack = document.getElementById("track-recommended");
  if (exploreAllBtn && recommendedTrack) {
    exploreAllBtn.addEventListener("click", () => {
      appState.showAllRecommended = !appState.showAllRecommended;
      recommendedTrack.classList.toggle("is-expanded-grid", appState.showAllRecommended);
      exploreAllBtn.textContent = appState.showAllRecommended
        ? "COLLAPSE TO CAROUSEL"
        : "EXPLORE ALL 8 VEHICLES";
      renderAllCarousels();
    });
  }

  // Event delegation for favorite toggles, card inspection, and reserve buttons
  document.addEventListener("click", (event) => {
    const favBtn = event.target.closest("[data-favorite-id]");
    if (favBtn) {
      const id = favBtn.getAttribute("data-favorite-id");
      if (appState.favorites.has(id)) {
        appState.favorites.delete(id);
        showToast("Removed from your Obsidian Garage.");
      } else {
        appState.favorites.add(id);
        showToast("Saved to your Obsidian Garage.");
      }
      renderAllCarousels();
      return;
    }

    const reserveBtn = event.target.closest("[data-reserve-id]");
    if (reserveBtn) {
      const id = reserveBtn.getAttribute("data-reserve-id");
      recordRecentlyViewed(id);
      openReserveModal(id);
      return;
    }

    const inspectCard = event.target.closest("[data-inspect-id], .car-image-placeholder, .car-photo-img");
    if (inspectCard) {
      const card = inspectCard.closest("[data-vehicle-id]");
      if (card) {
        const id = card.getAttribute("data-vehicle-id");
        const vehicle = VEHICLE_CATALOG.find((v) => v.id === id);
        recordRecentlyViewed(id);
        if (vehicle) {
          showToast(`${vehicle.title} synced to Recently Viewed.`);
        }
      }
    }
  });
}

/* ==========================================================================
   18-PAGE NAVIGATOR & RESERVATION MODALS
   ========================================================================== */
function openModal(modalId) {
  const modal = document.getElementById(modalId);
  if (modal) modal.hidden = false;
}

function closeModal(modalId) {
  const modal = document.getElementById(modalId);
  if (modal) modal.hidden = true;
}

function renderNavigatorModules() {
  const grid = document.getElementById("navigatorModuleGrid");
  const badge = document.getElementById("activeModuleBadge");
  if (!grid) return;

  grid.innerHTML = PROTOTYPE_MODULES.map(
    (mod) => `
      <button
        type="button"
        class="navigator-module-card ${mod.num === appState.activeModule ? "is-current" : ""}"
        data-select-module="${mod.num}"
      >
        <span class="module-num">MODULE ${mod.num}/18</span>
        <span class="module-name">${mod.title}</span>
      </button>
    `
  ).join("");

  if (badge) {
    badge.textContent = `${appState.activeModule}/18`;
  }
}

function openReserveModal(preselectedId = VEHICLE_CATALOG[0].id, withChauffeur = false) {
  const select = document.getElementById("reserveVehicleSelect");
  const chauffeurToggle = document.getElementById("reserveChauffeurToggle");
  if (select) {
    select.value = preselectedId;
  }
  if (chauffeurToggle) {
    chauffeurToggle.checked = withChauffeur;
  }
  updateReserveSummary();
  openModal("reserveModal");
}

function updateReserveSummary() {
  const select = document.getElementById("reserveVehicleSelect");
  const daysInput = document.getElementById("reserveDaysInput");
  const chauffeurToggle = document.getElementById("reserveChauffeurToggle");
  const totalDisplay = document.getElementById("reserveTotalDisplay");
  if (!select || !daysInput || !chauffeurToggle || !totalDisplay) return;

  const vehicle = VEHICLE_CATALOG.find((v) => v.id === select.value) || VEHICLE_CATALOG[0];
  const days = Math.max(1, Number(daysInput.value) || 1);
  const chauffeurCost = chauffeurToggle.checked ? 450 * days : 0;
  const total = vehicle.dailyPrice * days + chauffeurCost;
  totalDisplay.textContent = formatCurrency(total);
}

function setupModalsAndNavigation() {
  // Populate vehicle select in reservation modal
  const reserveSelect = document.getElementById("reserveVehicleSelect");
  if (reserveSelect) {
    reserveSelect.innerHTML = VEHICLE_CATALOG.map(
      (v) => `<option value="${v.id}">${v.title} (${formatCurrency(v.dailyPrice)}/day)</option>`
    ).join("");
  }

  renderNavigatorModules();

  // Navigator triggers
  ["openNavigatorTop", "floatingNavigatorBtn", "mobileNavigatorBtn"].forEach((id) => {
    const btn = document.getElementById(id);
    if (btn) {
      btn.addEventListener("click", () => openModal("navigatorModal"));
    }
  });

  // Reservation triggers
  ["headerReserveBtn", "mobileReserveBtn"].forEach((id) => {
    const btn = document.getElementById(id);
    if (btn) btn.addEventListener("click", () => openReserveModal());
  });

  const chauffeurBtn = document.getElementById("heroChauffeurBtn");
  if (chauffeurBtn) {
    chauffeurBtn.addEventListener("click", () => openReserveModal("rr-spectre-bb", true));
  }

  const pairChauffeurBtn = document.getElementById("pairChauffeurBtn");
  if (pairChauffeurBtn) {
    pairChauffeurBtn.addEventListener("click", () => openReserveModal("maybach-s680-hv", true));
  }

  const memberOffersBtn = document.getElementById("memberOffersBtn");
  if (memberOffersBtn) {
    memberOffersBtn.addEventListener("click", () => {
      showToast("Obsidian Member Offer: 15% off Chauffeur Packages & Complimentary Tarmac Delivery.");
    });
  }

  const memberProfileBtn = document.getElementById("memberProfileBtn");
  if (memberProfileBtn) {
    memberProfileBtn.addEventListener("click", () => {
      showToast(`Alexander · Obsidian Tier Active (${appState.favorites.size} Saved Vehicles)`);
    });
  }

  // Close modal buttons & backdrop click
  document.querySelectorAll("[data-close-modal]").forEach((btn) => {
    btn.addEventListener("click", () => closeModal(btn.getAttribute("data-close-modal")));
  });

  document.querySelectorAll(".modal-backdrop").forEach((backdrop) => {
    backdrop.addEventListener("click", (e) => {
      if (e.target === backdrop) backdrop.hidden = true;
    });
  });

  // Select module inside 18-Page Navigator or footer
  document.addEventListener("click", (e) => {
    const modBtn = e.target.closest("[data-select-module]");
    if (modBtn) {
      const num = modBtn.getAttribute("data-select-module");
      const mod = PROTOTYPE_MODULES.find((m) => m.num === num);
      appState.activeModule = num;
      renderNavigatorModules();
      closeModal("navigatorModal");
      if (mod) {
        document.querySelector(mod.target)?.scrollIntoView({ behavior: "smooth" });
        showToast(`Active Module ${mod.num}/18: ${mod.title}`);
      }
    }

    const footerMod = e.target.closest("[data-module]");
    if (footerMod) {
      appState.activeModule = footerMod.getAttribute("data-module");
      renderNavigatorModules();
    }
  });

  // Live reservation summary updates
  ["reserveVehicleSelect", "reserveDaysInput", "reserveChauffeurToggle"].forEach((id) => {
    const el = document.getElementById(id);
    if (el) el.addEventListener("change", updateReserveSummary);
    if (el) el.addEventListener("input", updateReserveSummary);
  });

  const reserveForm = document.getElementById("reserveForm");
  if (reserveForm) {
    reserveForm.addEventListener("submit", (e) => {
      e.preventDefault();
      const select = document.getElementById("reserveVehicleSelect");
      const hub = document.getElementById("reserveHubSelect");
      const vehicle = VEHICLE_CATALOG.find((v) => v.id === select?.value);
      closeModal("reserveModal");
      showToast(
        `Concierge hold confirmed for ${vehicle ? vehicle.title : "your vehicle"} in ${hub?.value || "Dubai"}.`
      );
    });
  }

  // Header active link state
  document.querySelectorAll(".main-nav .nav-link").forEach((link) => {
    link.addEventListener("click", () => {
      document.querySelectorAll(".main-nav .nav-link").forEach((l) => l.classList.remove("is-active"));
      link.classList.add("is-active");
    });
  });

  // Mobile menu toggle
  const mobileToggle = document.getElementById("mobileMenuToggle");
  const mobileDrawer = document.getElementById("mobileDrawer");
  if (mobileToggle && mobileDrawer) {
    mobileToggle.addEventListener("click", () => {
      const isHidden = mobileDrawer.hidden;
      mobileDrawer.hidden = !isHidden;
      mobileToggle.setAttribute("aria-expanded", String(isHidden));
    });
    mobileDrawer.querySelectorAll("a, button").forEach((item) => {
      item.addEventListener("click", () => {
        mobileDrawer.hidden = true;
        mobileToggle.setAttribute("aria-expanded", "false");
      });
    });
  }

  // Escape key closes modals
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      closeModal("navigatorModal");
      closeModal("reserveModal");
    }
  });
}

/* ==========================================================================
   INITIALIZE
   ========================================================================== */
document.addEventListener("DOMContentLoaded", () => {
  renderAllCarousels();
  setupVaultStage();
  setupCarouselsAndCards();
  setupModalsAndNavigation();
});

/* ==========================================================================
   RENT RIDE · CURATED LUXURY FLEET (PAGE 02)
   Luxury Dark-Mode Design System & Catalog Styles
   ========================================================================== */

:root {
  /* Core Obsidian Palette */
  --bg-obsidian: #080705;
  --bg-onyx: #0d0b07;
  --bg-card: #12100b;
  --bg-card-elevated: #17140e;
