.mobile-menu-toggle span {
  display: block;
  height: 1.5px;
  width: 100%;
  background: var(--gold-primary);
}

.mobile-drawer {
  position: absolute;
  top: var(--header-height);
  left: 0;
  right: 0;
  background: rgba(10, 9, 6, 0.98);
  border-bottom: 1px solid var(--gold-border);
  padding: 20px 24px 24px;
}

.mobile-nav {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 18px;
}

.mobile-nav-link {
  font-size: 0.95rem;
  color: var(--text-secondary);
  padding: 6px 0;
}

.mobile-nav-link.is-active {
  color: var(--gold-bright);
}

.mobile-drawer-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

/* ==========================================================================
   3. CATALOG HEADER & FILTER PANEL
   ========================================================================== */
.catalog-header-section {
  padding: 46px 0 28px;
}

.catalog-header-top {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 28px;
}

.catalog-heading-block {
  max-width: 720px;
}

.page-kicker {
  margin: 0 0 10px;
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--gold-primary);
}

.catalog-title {
  margin: 0 0 12px;
  font-family: var(--font-serif);
  font-size: clamp(2.3rem, 4.4vw, 3.45rem);
  font-weight: 600;
  line-height: 1.02;
  letter-spacing: 0.02em;
  color: var(--text-primary);
}

.catalog-subtitle {
  margin: 0;
  font-size: 0.96rem;
  line-height: 1.6;
  color: var(--text-secondary);
}

.catalog-count-pill {
  flex-shrink: 0;
  padding: 10px 18px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--gold-border);
  background: rgba(18, 16, 11, 0.88);
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  color: var(--gold-bright);
}

/* Filter & Sort Control Panel */
.filter-panel {
  border-radius: var(--radius-lg);
  border: 1px solid var(--gold-border);
  background: linear-gradient(180deg, rgba(20, 17, 12, 0.94) 0%, rgba(12, 10, 7, 0.97) 100%);
  padding: 22px 24px;
  box-shadow: var(--shadow-card);
}

.filter-controls-grid {
  display: grid;
  grid-template-columns: 1.45fr 1fr 1.15fr 1fr;
  gap: 18px;
  align-items: end;
  padding-bottom: 18px;
  border-bottom: 1px solid rgba(212, 175, 55, 0.14);
}

.filter-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.filter-label {
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.slider-price-val {
  color: var(--gold-bright);
}

.input-icon-wrap {
  position: relative;
  display: flex;
  align-items: center;
}

.field-icon {
  position: absolute;
  left: 13px;
  width: 14px;
  height: 14px;
  color: var(--gold-primary);
  pointer-events: none;
}

.filter-input,
.filter-select {
  width: 100%;
  height: 42px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--gold-border);
  background: rgba(8, 7, 5, 0.9);
  color: var(--text-primary);
  font-family: inherit;
  font-size: 0.84rem;
  transition: border-color var(--transition-fast);
}

.filter-input {
  padding: 0 14px 0 38px;
}

.filter-input::placeholder {
  color: var(--text-muted);
}

.filter-select {
  padding: 0 12px;
  cursor: pointer;
}

.filter-input:focus,
.filter-select:focus {
  outline: none;
  border-color: var(--gold-primary);
}

/* Gold Range Slider */
.slider-wrap {
  height: 42px;
  display: flex;
  align-items: center;
  padding: 0 4px;
}

.gold-slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 4px;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--gold-primary) 100%, rgba(255, 255, 255, 0.12) 100%);
  outline: none;
  cursor: pointer;
}

.gold-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--gold-bright);
  border: 2px solid #0b0905;
  box-shadow: 0 0 12px rgba(212, 175, 55, 0.6);
  cursor: pointer;
}

.gold-slider::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--gold-bright);
  border: 2px solid #0b0905;
  box-shadow: 0 0 12px rgba(212, 175, 55, 0.6);
  cursor: pointer;
}

/* Category Pills Row */
.category-pills-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  padding-top: 16px;
}

.category-pill {
  height: 34px;
  padding: 0 16px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--gold-border);
  background: rgba(10, 9, 6, 0.7);
  font-size: 0.76rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.category-pill:hover {
  border-color: var(--gold-border-strong);
  color: var(--text-primary);
}

.category-pill.is-active {
  background: linear-gradient(135deg, var(--gold-bright) 0%, var(--gold-primary) 100%);
  border-color: transparent;
  color: #0b0905;
  font-weight: 700;
  box-shadow: 0 4px 16px rgba(212, 175, 55, 0.25);
}

/* ==========================================================================
   4. FLEET GRID & VEHICLE CARDS (3-COLUMN RESPONSIVE)
   ========================================================================== */
.fleet-grid-section {
  padding: 6px 0 84px;
}

.fleet-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
}

.vehicle-card {
  display: flex;
  flex-direction: column;
  border-radius: var(--radius-md);
  border: 1px solid var(--gold-border);
  background: linear-gradient(180deg, var(--bg-card-elevated) 0%, var(--bg-card) 100%);
  overflow: hidden;
  transition: transform var(--transition-smooth), border-color var(--transition-fast), box-shadow var(--transition-smooth);
}

.vehicle-card:hover {
  transform: translateY(-4px);
  border-color: var(--gold-border-strong);
  box-shadow: 0 22px 46px rgba(0, 0, 0, 0.62), 0 0 28px rgba(212, 175, 55, 0.08);
}

/* Card Media & Styled Image Placeholder */
.card-media {
  position: relative;
  height: 224px;
  border-bottom: 1px solid rgba(212, 175, 55, 0.14);
  background: var(--bg-studio);
  overflow: hidden;
}

.car-image-placeholder {
  position: relative;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 20px;
  text-align: center;
  background:
    radial-gradient(ellipse 75% 48% at 50% 42%, rgba(212, 175, 55, 0.14) 0%, rgba(212, 175, 55, 0.03) 55%, transparent 80%),
    linear-gradient(180deg, #17140d 0%, #0b0906 72%, #13100a 100%);
}

.car-image-placeholder::before {
  content: "";
  position: absolute;
  inset: 14px;
  border: 1px dashed rgba(212, 175, 55, 0.16);
  border-radius: 8px;
  pointer-events: none;
}

.car-image-placeholder::after {
  content: "";
  position: absolute;
  left: 12%;
  right: 12%;
  bottom: 38px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(212, 175, 55, 0.35), transparent);
  pointer-events: none;
}

.placeholder-icon {
  width: 48px;
  height: 24px;
  color: rgba(212, 175, 55, 0.68);
}

.placeholder-label {
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--gold-bright);
  opacity: 0.92;
}

.placeholder-slot-hint {
  font-size: 0.64rem;
  color: var(--text-muted);
  letter-spacing: 0.04em;
}

.car-photo-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* Overlay Tags & Badges */
.card-overlay-top {
  position: absolute;
  top: 12px;
  left: 12px;
  right: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  pointer-events: none;
}

.studio-tag {
  padding: 5px 10px;
  border-radius: var(--radius-pill);
  background: rgba(8, 7, 5, 0.78);
  border: 1px solid rgba(255, 255, 255, 0.12);
  backdrop-filter: blur(8px);
  font-size: 0.6rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  color: var(--text-secondary);
}

.favorite-btn {
  pointer-events: auto;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: rgba(8, 7, 5, 0.82);
  border: 1px solid rgba(212, 175, 55, 0.28);
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.favorite-btn svg {
  width: 15px;
  height: 15px;
}

.favorite-btn:hover {
  border-color: var(--gold-primary);
  color: var(--gold-bright);
}

.favorite-btn.is-favorited {
  background: rgba(212, 175, 55, 0.22);
  border-color: var(--gold-primary);
  color: var(--gold-bright);
  box-shadow: 0 0 14px rgba(212, 175, 55, 0.32);
}

.favorite-btn.is-favorited svg {
  fill: currentColor;
}

.card-overlay-bottom {
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  pointer-events: none;
}

.perk-badge {
  padding: 4px 9px;
  border-radius: var(--radius-pill);
  background: linear-gradient(135deg, rgba(212, 175, 55, 0.94), rgba(188, 146, 36, 0.94));
  color: #0b0905;
  font-size: 0.56rem;
  font-weight: 700;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 72%;
}

.spec-badge {
  margin-left: auto;
  padding: 4px 8px;
  border-radius: var(--radius-pill);
  background: rgba(8, 7, 5, 0.84);
  border: 1px solid rgba(212, 175, 55, 0.28);
  font-size: 0.58rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  color: var(--gold-bright);
  white-space: nowrap;
}

/* Card Body */
.card-body {
  display: flex;
  flex-direction: column;
  flex: 1;
  padding: 18px 20px 20px;
}

.card-meta-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 8px;
}

.category-kicker {
  font-size: 0.62rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--gold-primary);
}

.rating-badge {
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--text-primary);
}

.rating-badge .star {
  color: var(--gold-primary);
}

.rating-count {
  color: var(--text-muted);
  font-weight: 400;
}

.vehicle-title {
  margin: 0 0 14px;
  font-family: var(--font-serif);
  font-size: 1.28rem;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: 0.02em;
  color: var(--text-primary);
  min-height: 3.05rem;
}

.specs-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 7px;
  margin-bottom: 18px;
}

.spec-pill {
  padding: 4px 10px;
  border-radius: var(--radius-pill);
  border: 1px solid rgba(255, 255, 255, 0.09);
  background: rgba(255, 255, 255, 0.03);
  font-size: 0.68rem;
  font-weight: 500;
  color: var(--text-secondary);
}

.status-pill-available {
  margin-left: auto;
  padding: 4px 10px;
  border-radius: var(--radius-pill);
  background: var(--status-green-bg);
  border: 1px solid var(--status-green-border);
  color: var(--status-green);
  font-size: 0.66rem;
  font-weight: 600;
}

.card-footer {
  margin-top: auto;
  padding-top: 14px;
  border-top: 1px solid rgba(212, 175, 55, 0.14);
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
}

.price-label {
  display: block;
  font-size: 0.58rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  color: var(--text-muted);
  margin-bottom: 3px;
}

.price-value {
  font-family: var(--font-serif);
  font-size: 1.46rem;
  font-weight: 700;
  color: var(--gold-bright);
  line-height: 1;
}

.price-unit {
  font-family: var(--font-sans);
  font-size: 0.72rem;
  font-weight: 500;
  color: var(--text-secondary);
}

.reserve-card-btn {
  height: 36px;
  padding: 0 18px;
  border-radius: var(--radius-pill);
  background: linear-gradient(135deg, var(--gold-bright) 0%, var(--gold-primary) 100%);
  color: #0b0905;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  transition: all var(--transition-fast);
}

.reserve-card-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 6px 18px rgba(212, 175, 55, 0.34);
}

/* Empty State */
.fleet-empty-state {
  text-align: center;
  padding: 58px 24px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gold-border);
  background: rgba(16, 14, 10, 0.85);
}

.empty-kicker {
  margin: 0 0 8px;
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.22em;
  color: var(--gold-primary);
}

.empty-title {
  margin: 0 0 10px;
  font-family: var(--font-serif);
  font-size: 2rem;
  font-weight: 600;
}

.empty-copy {
  margin: 0 auto 22px;
  max-width: 480px;
  font-size: 0.9rem;
  color: var(--text-secondary);
}

/* ==========================================================================
   5. FOOTER
   ========================================================================== */
.site-footer {
  border-top: 1px solid var(--gold-border);
  background: linear-gradient(180deg, #0b0906 0%, #060503 100%);
  padding: 58px 0 92px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.45fr repeat(3, minmax(0, 1fr));
  gap: 40px;
  padding-bottom: 42px;
  border-bottom: 1px solid rgba(212, 175, 55, 0.14);
}

.footer-brand-lockup {
  margin-bottom: 18px;
}

.footer-description {
  margin: 0 0 20px;
  max-width: 360px;
  font-size: 0.86rem;
  line-height: 1.65;
  color: var(--text-secondary);
}

.footer-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.footer-pill {
  padding: 6px 12px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--gold-border);
  background: rgba(18, 16, 11, 0.8);
  font-size: 0.72rem;
  color: var(--text-secondary);
}

.footer-pill-gold {
  border-color: rgba(212, 175, 55, 0.36);
  color: var(--gold-bright);
}

.footer-col-title {
  margin: 0 0 16px;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--gold-primary);
}

.footer-links {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-links a {
  font-size: 0.82rem;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.footer-links a:hover {
  color: var(--gold-bright);
}

.footer-bottom {
  padding-top: 24px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.footer-status {
  margin: 0;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-size: 0.78rem;
  color: var(--text-secondary);
}

.sync-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--status-green);
  box-shadow: 0 0 8px rgba(74, 222, 128, 0.65);
}

.footer-cities {
  margin: 0;
  font-size: 0.76rem;
  letter-spacing: 0.12em;
  color: var(--text-muted);
}

/* ==========================================================================
   FLOATING BOTTOM-LEFT 18-PAGE NAVIGATOR PILL
   ========================================================================== */
.floating-navigator-pill {
  position: fixed;
  left: 22px;
  bottom: 22px;
  z-index: 70;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  height: 42px;
  padding: 0 14px 0 16px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--gold-border-strong);
  background: rgba(12, 10, 7, 0.92);
  backdrop-filter: blur(14px);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.65), 0 0 18px rgba(212, 175, 55, 0.14);
  transition: transform var(--transition-fast), border-color var(--transition-fast);
}

.floating-navigator-pill:hover {
  transform: translateY(-2px);
  border-color: var(--gold-bright);
}

.nav-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gold-primary);
  box-shadow: 0 0 10px var(--gold-primary);
}

.nav-pill-text {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--text-primary);
}

.nav-pill-badge {
  padding: 3px 8px;
  border-radius: var(--radius-pill);
  background: rgba(212, 175, 55, 0.16);
  border: 1px solid rgba(212, 175, 55, 0.35);
  font-size: 0.68rem;
  font-weight: 700;
  color: var(--gold-bright);
}

/* ==========================================================================
   MODALS & TOAST
   ========================================================================== */
.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 90;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(4, 3, 2, 0.78);
  backdrop-filter: blur(10px);
}

.modal-backdrop[hidden] {
  display: none;
}

.modal-panel {
  width: min(560px, 100%);
  max-height: 86vh;
  overflow-y: auto;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gold-border-strong);
  background: linear-gradient(180deg, #16130d 0%, #0b0906 100%);
  padding: 26px;
  box-shadow: 0 28px 70px rgba(0, 0, 0, 0.8);
}

.modal-panel-wide {
  width: min(860px, 100%);
}

.modal-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 22px;
}

.modal-kicker {
  margin: 0 0 4px;
  font-size: 0.66rem;
  font-weight: 600;
  letter-spacing: 0.2em;
  color: var(--gold-primary);
}

.modal-title {
  margin: 0;
  font-family: var(--font-serif);
  font-size: 1.7rem;
  font-weight: 600;
  color: var(--text-primary);
}

.modal-close {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1px solid var(--gold-border);
  color: var(--text-secondary);
  display: grid;
  place-items: center;
}

.modal-close:hover {
  border-color: var(--gold-primary);
  color: var(--gold-bright);
}

.navigator-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.navigator-module-card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  padding: 12px 14px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--gold-border);
  background: rgba(18, 16, 11, 0.75);
  text-align: left;
  transition: all var(--transition-fast);
}

.navigator-module-card:hover,
.navigator-module-card.is-current {
  border-color: var(--gold-primary);
  background: rgba(212, 175, 55, 0.12);
}

.module-num {
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--gold-primary);
}

.module-name {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text-primary);
}

.reserve-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.form-grid-2 {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.form-row {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.form-label {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-secondary);
}

.form-control {
  height: 42px;
  padding: 0 12px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--gold-border);
  background: #0a0906;
  color: var(--text-primary);
  font-family: inherit;
  font-size: 0.86rem;
}

.form-control:focus {
  outline: none;
  border-color: var(--gold-primary);
}

.form-checkbox {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.84rem;
  color: var(--text-secondary);
  cursor: pointer;
}

.form-checkbox input {
  accent-color: var(--gold-primary);
}

.reserve-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 16px;
  border-radius: var(--radius-md);
  border: 1px solid var(--gold-border);
  background: rgba(212, 175, 55, 0.06);
