/* ==========================================================================
   HELPERS & RENDERING
   ========================================================================== */
function formatCurrency(amount) {
  return "$" + Number(amount).toLocaleString("en-US");
}

function showToast(message) {
  const toast = document.getElementById("atelierToast");
  if (!toast) return;
  toast.textContent = message;
  toast.hidden = false;
  clearTimeout(showToast._timer);
  showToast._timer = setTimeout(() => {
    toast.hidden = true;
  }, 3200);
}

/**
 * Renders the styled image placeholder box when `imageUrl` is empty,
 * or the real photo <img> once `imageUrl` is populated in FLEET_CATALOG.
 */
function renderVehicleMedia(vehicle) {
  if (vehicle.imageUrl && vehicle.imageUrl.trim() !== "") {
    return `<img class="car-photo-img" src="${vehicle.imageUrl}" alt="${vehicle.title}" loading="lazy" />`;
  }

  return `
    <div class="car-image-placeholder" data-slot="${vehicle.slot}">
      <svg class="placeholder-icon" viewBox="0 0 64 28" fill="none" aria-hidden="true">
        <path d="M5 20C7 14 14 11 22 10L30 5C37 3 47 4 54 9L59 14C61 15 62 17 61 20H53M19 20H5" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/>
        <circle cx="15" cy="21" r="4" stroke="currentColor" stroke-width="1.6"/>
        <circle cx="49" cy="21" r="4" stroke="currentColor" stroke-width="1.6"/>
      </svg>
      <span class="placeholder-label">${vehicle.placeholderLabel}</span>
      <span class="placeholder-slot-hint">${vehicle.slot}</span>
    </div>
  `;
}

function createVehicleCardHTML(vehicle) {
  const isFav = catalogState.favorites.has(vehicle.id);
  const perkHTML = vehicle.perkBadge
    ? `<span class="perk-badge">${vehicle.perkBadge}</span>`
    : "";

  return `
    <article class="vehicle-card" data-vehicle-id="${vehicle.id}">
      <div class="card-media">
        ${renderVehicleMedia(vehicle)}

        <div class="card-overlay-top">
          <span class="studio-tag">${vehicle.studioTag}</span>
          <button
            type="button"
            class="favorite-btn ${isFav ? "is-favorited" : ""}"
            data-favorite-id="${vehicle.id}"
            aria-label="Save ${vehicle.title} to Obsidian Garage"
            aria-pressed="${isFav}"
          >
            <svg viewBox="0 0 20 20" fill="none" aria-hidden="true">
              <path d="M10 17.25C10 17.25 3 12.6 3 7.35C3 5.1 4.75 3.35 6.95 3.35C8.28 3.35 9.45 4.02 10 5.05C10.55 4.02 11.72 3.35 13.05 3.35C15.25 3.35 17 5.1 17 7.35C17 12.6 10 17.25 10 17.25Z" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/>
            </svg>
          </button>
        </div>

        <div class="card-overlay-bottom">
          ${perkHTML}
          <span class="spec-badge tabular">${vehicle.specYear}</span>
        </div>
      </div>

      <div class="card-body">
        <div class="card-meta-top">
          <span class="category-kicker">${vehicle.category.toUpperCase()}</span>
          <span class="rating-badge tabular">
            <span class="star">★</span> ${vehicle.rating.toFixed(2)}
            <span class="rating-count">(${vehicle.reviews})</span>
          </span>
        </div>

        <h2 class="vehicle-title">${vehicle.title}</h2>

        <div class="specs-row">
          <span class="spec-pill">${vehicle.location}</span>
          <span class="spec-pill tabular">${vehicle.power}</span>
          <span class="status-pill-available">${vehicle.status}</span>
        </div>

        <div class="card-footer">
          <div>
            <span class="price-label">DAILY PRIVILEGE</span>
            <span class="price-value tabular">${formatCurrency(vehicle.dailyPrice)} <span class="price-unit">/day</span></span>
          </div>
          <button type="button" class="reserve-card-btn" data-reserve-id="${vehicle.id}">
            RESERVE
          </button>
        </div>
      </div>
    </article>
  `;
}

function getFilteredAndSortedVehicles() {
  const query = catalogState.searchQuery.trim().toLowerCase();

  const filtered = FLEET_CATALOG.filter((vehicle) => {
    const matchesSearch =
      query === "" ||
      vehicle.title.toLowerCase().includes(query) ||
      vehicle.category.toLowerCase().includes(query) ||
      vehicle.city.toLowerCase().includes(query);

    const matchesHub =
      catalogState.selectedHub === "all" ||
      vehicle.city.toLowerCase() === catalogState.selectedHub.toLowerCase();

    const matchesRate = vehicle.dailyPrice <= catalogState.maxDailyRate;

    const matchesCategory =
      catalogState.selectedCategory === "All" ||
      vehicle.category.toLowerCase() === catalogState.selectedCategory.toLowerCase();

    return matchesSearch && matchesHub && matchesRate && matchesCategory;
  });

  return filtered.sort((a, b) => {
    switch (catalogState.sortBy) {
      case "price-desc":
        return b.dailyPrice - a.dailyPrice;
      case "price-asc":
        return a.dailyPrice - b.dailyPrice;
      case "rating-desc":
        return b.rating - a.rating;
      case "prestige":
      default:
        return a.prestigeOrder - b.prestigeOrder;
    }
  });
}

function renderFleetGrid() {
  const grid = document.getElementById("fleetGrid");
  const emptyState = document.getElementById("fleetEmptyState");
  const countBadge = document.getElementById("vehicleCountBadge");
  if (!grid || !emptyState || !countBadge) return;

  const vehicles = getFilteredAndSortedVehicles();
  const totalCount = FLEET_CATALOG.length;

  countBadge.textContent = `Showing ${vehicles.length} of ${totalCount} Concours Vehicles`;

  if (vehicles.length === 0) {
    grid.innerHTML = "";
    emptyState.hidden = false;
    return;
  }

  emptyState.hidden = true;
  grid.innerHTML = vehicles.map(createVehicleCardHTML).join("");
}

/* ==========================================================================
   FILTER & SLIDER CONTROLS
   ========================================================================== */
function updateSliderTrackFill(slider) {
  const min = Number(slider.min);
  const max = Number(slider.max);
  const val = Number(slider.value);
  const pct = ((val - min) / (max - min)) * 100;
  slider.style.background = `linear-gradient(90deg, #d4af37 ${pct}%, rgba(255, 255, 255, 0.12) ${pct}%)`;
}

function setActiveCategoryPill(category) {
  catalogState.selectedCategory = category;
  document.querySelectorAll(".category-pill").forEach((pill) => {
    const isMatch = pill.getAttribute("data-category") === category;
    pill.classList.toggle("is-active", isMatch);
    pill.setAttribute("aria-selected", String(isMatch));
  });
  renderFleetGrid();
}

function resetAllFilters() {
  catalogState.searchQuery = "";
  catalogState.selectedHub = "all";
  catalogState.maxDailyRate = 3500;
  catalogState.sortBy = "prestige";
  catalogState.selectedCategory = "All";

  const searchInput = document.getElementById("searchFleetInput");
  const hubSelect = document.getElementById("hubFilterSelect");
  const slider = document.getElementById("maxPriceSlider");
  const sliderVal = document.getElementById("maxPriceValue");
  const sortSelect = document.getElementById("sortFleetSelect");

  if (searchInput) searchInput.value = "";
  if (hubSelect) hubSelect.value = "all";
  if (slider) {
    slider.value = "3500";
    updateSliderTrackFill(slider);
  }
  if (sliderVal) sliderVal.textContent = "$3,500";
  if (sortSelect) sortSelect.value = "prestige";

  setActiveCategoryPill("All");
}

function setupFilters() {
  const searchInput = document.getElementById("searchFleetInput");
  const hubSelect = document.getElementById("hubFilterSelect");
  const slider = document.getElementById("maxPriceSlider");
  const sliderVal = document.getElementById("maxPriceValue");
  const sortSelect = document.getElementById("sortFleetSelect");
  const resetBtn = document.getElementById("resetFiltersBtn");

  if (searchInput) {
    searchInput.addEventListener("input", (e) => {
      catalogState.searchQuery = e.target.value;
      renderFleetGrid();
    });
  }

  if (hubSelect) {
    hubSelect.addEventListener("change", (e) => {
      catalogState.selectedHub = e.target.value;
      renderFleetGrid();
    });
  }

  if (slider && sliderVal) {
    updateSliderTrackFill(slider);
    slider.addEventListener("input", (e) => {
      const rate = Number(e.target.value);
      catalogState.maxDailyRate = rate;
      sliderVal.textContent = formatCurrency(rate);
      updateSliderTrackFill(slider);
      renderFleetGrid();
    });
  }

  if (sortSelect) {
    sortSelect.addEventListener("change", (e) => {
      catalogState.sortBy = e.target.value;
      renderFleetGrid();
    });
  }

  document.querySelectorAll(".category-pill").forEach((pill) => {
    pill.addEventListener("click", () => {
      setActiveCategoryPill(pill.getAttribute("data-category"));
    });
  });

  if (resetBtn) {
    resetBtn.addEventListener("click", resetAllFilters);
  }

  // Quick-filter links (e.g. "Chauffeurs" nav link)
  document.querySelectorAll("[data-quick-category]").forEach((link) => {
    link.addEventListener("click", (e) => {
      e.preventDefault();
      setActiveCategoryPill(link.getAttribute("data-quick-category"));
      document.getElementById("fleet-catalog")?.scrollIntoView({ behavior: "smooth" });
    });
  });

  // Favorite toggle & Reserve button delegation
  document.addEventListener("click", (e) => {
    const favBtn = e.target.closest("[data-favorite-id]");
    if (favBtn) {
      const id = favBtn.getAttribute("data-favorite-id");
      if (catalogState.favorites.has(id)) {
        catalogState.favorites.delete(id);
        showToast("Removed from your Obsidian Garage.");
      } else {
        catalogState.favorites.add(id);
        showToast("Saved to your Obsidian Garage.");
      }
      renderFleetGrid();
      return;
    }

    const reserveBtn = e.target.closest("[data-reserve-id]");
    if (reserveBtn) {
      openReserveModal(reserveBtn.getAttribute("data-reserve-id"));
    }
  });
}

/* ==========================================================================
   18-PAGE NAVIGATOR & RESERVATION MODALS
   ========================================================================== */
function openModal(modalId) {
  const modal = document.getElementById(modalId);
  if (modal) modal.hidden = false;
}

function closeModal(modalId) {
  const modal = document.getElementById(modalId);
  if (modal) modal.hidden = true;
}

function renderNavigatorModules() {
  const grid = document.getElementById("navigatorModuleGrid");
  const badge = document.getElementById("activeModuleBadge");
  if (!grid) return;

  grid.innerHTML = PROTOTYPE_MODULES.map(
    (mod) => `
      <button
        type="button"
        class="navigator-module-card ${mod.num === catalogState.activeModule ? "is-current" : ""}"
        data-select-module="${mod.num}"
      >
        <span class="module-num">MODULE ${mod.num}/18</span>
        <span class="module-name">${mod.title}</span>
      </button>
    `
  ).join("");

  if (badge) {
    badge.textContent = `${catalogState.activeModule}/18`;
  }
}

function openReserveModal(preselectedId = FLEET_CATALOG[0].id) {
  const select = document.getElementById("reserveVehicleSelect");
  const hubSelect = document.getElementById("reserveHubSelect");
  const vehicle = FLEET_CATALOG.find((v) => v.id === preselectedId) || FLEET_CATALOG[0];

  if (select) select.value = vehicle.id;
  if (hubSelect && vehicle.city) hubSelect.value = vehicle.city;

  updateReserveSummary();
  openModal("reserveModal");
}

function updateReserveSummary() {
  const select = document.getElementById("reserveVehicleSelect");
  const daysInput = document.getElementById("reserveDaysInput");
  const chauffeurToggle = document.getElementById("reserveChauffeurToggle");
  const totalDisplay = document.getElementById("reserveTotalDisplay");
  if (!select || !daysInput || !chauffeurToggle || !totalDisplay) return;

  const vehicle = FLEET_CATALOG.find((v) => v.id === select.value) || FLEET_CATALOG[0];
  const days = Math.max(1, Number(daysInput.value) || 1);
  const chauffeurCost = chauffeurToggle.checked ? 450 * days : 0;
  totalDisplay.textContent = formatCurrency(vehicle.dailyPrice * days + chauffeurCost);
}

function setupModalsAndNavigation() {
  const reserveSelect = document.getElementById("reserveVehicleSelect");
  if (reserveSelect) {
    reserveSelect.innerHTML = FLEET_CATALOG.map(
      (v) => `<option value="${v.id}">${v.title} (${formatCurrency(v.dailyPrice)}/day)</option>`
    ).join("");
  }

  renderNavigatorModules();

  ["openNavigatorTop", "floatingNavigatorBtn", "mobileNavigatorBtn"].forEach((id) => {
    const btn = document.getElementById(id);
    if (btn) btn.addEventListener("click", () => openModal("navigatorModal"));
  });

  ["headerReserveBtn", "mobileReserveBtn"].forEach((id) => {
    const btn = document.getElementById(id);
    if (btn) btn.addEventListener("click", () => openReserveModal());
  });

  const memberProfileBtn = document.getElementById("memberProfileBtn");
  if (memberProfileBtn) {
    memberProfileBtn.addEventListener("click", () => {
      showToast(`Alexander · Obsidian Tier Active (${catalogState.favorites.size} Saved Vehicles)`);
    });
  }

  document.querySelectorAll("[data-close-modal]").forEach((btn) => {
    btn.addEventListener("click", () => closeModal(btn.getAttribute("data-close-modal")));
  });

  document.querySelectorAll(".modal-backdrop").forEach((backdrop) => {
    backdrop.addEventListener("click", (e) => {
      if (e.target === backdrop) backdrop.hidden = true;
    });
  });

  document.addEventListener("click", (e) => {
    const modBtn = e.target.closest("[data-select-module]");
    if (modBtn) {
      const num = modBtn.getAttribute("data-select-module");
      const mod = PROTOTYPE_MODULES.find((m) => m.num === num);
      catalogState.activeModule = num;
      renderNavigatorModules();
      closeModal("navigatorModal");
      if (mod) {
        if (mod.href.startsWith("#")) {
          document.querySelector(mod.href)?.scrollIntoView({ behavior: "smooth" });
          showToast(`Active Module ${mod.num}/18: ${mod.title}`);
        } else {
          window.location.href = mod.href;
        }
      }
    }

    const footerMod = e.target.closest("[data-module]");
    if (footerMod) {
      catalogState.activeModule = footerMod.getAttribute("data-module");
      renderNavigatorModules();
    }
  });

  ["reserveVehicleSelect", "reserveDaysInput", "reserveChauffeurToggle"].forEach((id) => {
    const el = document.getElementById(id);
    if (el) {
      el.addEventListener("change", updateReserveSummary);
      el.addEventListener("input", updateReserveSummary);
    }
  });

  const reserveForm = document.getElementById("reserveForm");
  if (reserveForm) {
    reserveForm.addEventListener("submit", (e) => {
      e.preventDefault();
      const select = document.getElementById("reserveVehicleSelect");
      const hub = document.getElementById("reserveHubSelect");
      const vehicle = FLEET_CATALOG.find((v) => v.id === select?.value);
      closeModal("reserveModal");
      showToast(
        `Concierge hold confirmed for ${vehicle ? vehicle.title : "your vehicle"} in ${hub?.value || "Dubai"}.`
      );
    });
  }

  // Mobile menu toggle
  const mobileToggle = document.getElementById("mobileMenuToggle");
  const mobileDrawer = document.getElementById("mobileDrawer");
  if (mobileToggle && mobileDrawer) {
    mobileToggle.addEventListener("click", () => {
      const isHidden = mobileDrawer.hidden;
      mobileDrawer.hidden = !isHidden;
      mobileToggle.setAttribute("aria-expanded", String(isHidden));
    });
    mobileDrawer.querySelectorAll("a, button").forEach((item) => {
      item.addEventListener("click", () => {
        mobileDrawer.hidden = true;
        mobileToggle.setAttribute("aria-expanded", "false");
      });
    });
  }

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      closeModal("navigatorModal");
      closeModal("reserveModal");
    }
  });
}

/* ==========================================================================
   INITIALIZE
   ========================================================================== */
document.addEventListener("DOMContentLoaded", () => {
  renderFleetGrid();
  setupFilters();
  setupModalsAndNavigation();
});

