/* ==========================================================================
   HELPERS & PLACEHOLDER RENDERING
   ========================================================================== */
function formatCurrency(amount) {
  return "$" + Number(amount).toLocaleString("en-US");
}

function showToast(message) {
  const toast = document.getElementById("atelierToast");
  if (!toast) return;
  toast.textContent = message;
  toast.hidden = false;
  clearTimeout(showToast._timer);
  showToast._timer = setTimeout(() => {
    toast.hidden = true;
  }, 3200);
}

function renderBookedVehicleMedia(showOverlayTags = true) {
  if (BOOKED_VEHICLE.imageUrl && BOOKED_VEHICLE.imageUrl.trim() !== "") {
    return `<img class="car-photo-img" src="${BOOKED_VEHICLE.imageUrl}" alt="${BOOKED_VEHICLE.title}" />`;
  }

  const tagsHTML = showOverlayTags
    ? `
      <div class="placeholder-overlay-tags">
        <span class="mini-studio-tag">${BOOKED_VEHICLE.studioTag}</span>
        <span class="mini-spec-tag tabular">${BOOKED_VEHICLE.specYear}</span>
      </div>
    `
    : "";

  return `
    <div class="car-image-placeholder" data-slot="${BOOKED_VEHICLE.slot}">
      ${tagsHTML}
      <svg class="placeholder-icon" viewBox="0 0 64 28" fill="none" aria-hidden="true">
        <path d="M5 20C7 14 14 11 22 10L30 5C37 3 47 4 54 9L59 14C61 15 62 17 61 20H53M19 20H5" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/>
        <circle cx="15" cy="21" r="4" stroke="currentColor" stroke-width="1.6"/>
        <circle cx="49" cy="21" r="4" stroke="currentColor" stroke-width="1.6"/>
      </svg>
      <span class="placeholder-label">${BOOKED_VEHICLE.placeholderLabel}</span>
    </div>
  `;
}

function renderVehicleSlots() {
  const checkoutThumb = document.getElementById("checkoutVehicleThumb");
  const passThumb = document.getElementById("passVehicleThumb");

  if (checkoutThumb) {
    checkoutThumb.innerHTML = renderBookedVehicleMedia(true);
  }
  if (passThumb) {
    passThumb.innerHTML = renderBookedVehicleMedia(false);
  }
}

function getTotalSettlement() {
  const gross =
    BOOKED_VEHICLE.baseCharter +
    BOOKED_VEHICLE.concoursPrep +
    BOOKED_VEHICLE.vatLevy -
    checkoutState.discountAmount;
  return Math.max(0, gross);
}

function updateTotalsAndPassCredentials() {
  const total = getTotalSettlement();
  const totalStr = formatCurrency(total);

  const totalDisplay = document.getElementById("totalSettlementDisplay");
  const passTotal = document.getElementById("passTotalSettled");
  if (totalDisplay) totalDisplay.textContent = totalStr;
  if (passTotal) passTotal.textContent = totalStr;

  const nameInput = document.getElementById("fullLegalNameInput");
  const emailInput = document.getElementById("privateEmailInput");
  const passName = document.getElementById("passPrincipalName");
  const passEmail = document.getElementById("passTokenEmail");

  if (passName && nameInput) {
    passName.textContent = (nameInput.value.trim() || "ALEXANDER VANCE").toUpperCase();
  }
  if (passEmail && emailInput) {
    passEmail.textContent = `Verified for ${emailInput.value.trim() || "a.vance@obsidianholdings.ch"}`;
  }
}

/* ==========================================================================
   VIEW SWITCHING (CHECKOUT 07/18 <-> BESPOKE PASS 08/18)
   ========================================================================== */
function switchView(viewName) {
  const isPass = viewName === "pass";
  checkoutState.currentView = isPass ? "pass" : "checkout";

  const checkoutView = document.getElementById("checkoutView");
  const passView = document.getElementById("passView");
  const stepCheckoutBtn = document.getElementById("stepCheckoutBtn");
  const stepPassBtn = document.getElementById("stepPassBtn");
  const badge = document.getElementById("activeModuleBadge");

  if (checkoutView) checkoutView.hidden = isPass;
  if (passView) passView.hidden = !isPass;

  if (stepCheckoutBtn && stepPassBtn) {
    stepCheckoutBtn.classList.toggle("is-active", !isPass);
    stepCheckoutBtn.classList.toggle("is-completed", isPass);
    stepPassBtn.classList.toggle("is-active", isPass);
  }

  if (badge) {
    badge.textContent = isPass ? "08/18" : "07/18";
  }

  updateTotalsAndPassCredentials();
  renderNavigatorModules();
  window.scrollTo({ top: 0, behavior: "smooth" });
}

/* ==========================================================================
   PRIVILEGE CODE, SETTLEMENT METHOD & FORM AUTHORIZATION
   ========================================================================== */
function setupCheckoutInteractions() {
  // Stepper switching
  document.querySelectorAll("[data-switch-view]").forEach((btn) => {
    btn.addEventListener("click", () => {
      switchView(btn.getAttribute("data-switch-view"));
    });
  });

  document.querySelectorAll("[data-step-info]").forEach((btn) => {
    btn.addEventListener("click", () => showToast(btn.getAttribute("data-step-info")));
  });

  // Privilege Code bar
  const applyBtn = document.getElementById("applyPrivilegeBtn");
  const codeInput = document.getElementById("privilegeCodeInput");
  const feedback = document.getElementById("privilegeFeedback");
  const discountRow = document.getElementById("privilegeDiscountRow");
  const discountVal = document.getElementById("privilegeDiscountVal");

  if (applyBtn && codeInput) {
    applyBtn.addEventListener("click", () => {
      const code = codeInput.value.trim().toUpperCase();
      if (!code) {
        showToast("Enter a privilege code such as OBSIDIAN10 or ATELIER.");
        return;
      }

      if (code === "OBSIDIAN10" || code === "ATELIER" || code === "VIP500") {
        checkoutState.discountAmount = 500;
        checkoutState.appliedCode = code;
        if (discountRow && discountVal) {
          discountRow.hidden = false;
          discountVal.textContent = `-${formatCurrency(500)}`;
        }
        if (feedback) {
          feedback.hidden = false;
          feedback.textContent = `Privilege code ${code} applied (-$500 Obsidian credit).`;
        }
      } else {
        checkoutState.discountAmount = 250;
        checkoutState.appliedCode = code;
        if (discountRow && discountVal) {
          discountRow.hidden = false;
          discountVal.textContent = `-${formatCurrency(250)}`;
        }
        if (feedback) {
          feedback.hidden = false;
          feedback.textContent = `Atelier privilege ${code} verified (-$250 concierge courtesy).`;
        }
      }

      updateTotalsAndPassCredentials();
      showToast(`Privilege code ${code} applied.`);
    });
  }

  // Settlement Method toggle
  const cardFields = document.getElementById("cardFieldsPanel");
  const altPanel = document.getElementById("altMethodPanel");
  const altTitle = document.getElementById("altMethodTitle");
  const altCopy = document.getElementById("altMethodCopy");

  document.querySelectorAll(".method-btn").forEach((btn) => {
    btn.addEventListener("click", () => {
      const method = btn.getAttribute("data-method");
      checkoutState.selectedMethod = method;

      document.querySelectorAll(".method-btn").forEach((m) => {
        const selected = m === btn;
        m.classList.toggle("is-selected", selected);
        m.setAttribute("aria-checked", String(selected));
      });

      if (method === "card") {
        if (cardFields) cardFields.hidden = false;
        if (altPanel) altPanel.hidden = true;
      } else {
        if (cardFields) cardFields.hidden = true;
        if (altPanel) altPanel.hidden = false;
        if (method === "wire" && altTitle && altCopy) {
          altTitle.textContent = "SWISS PRIVATE BANK WIRE · IBAN ESCROW";
          altCopy.textContent =
            "Reference token RR-WIRE-69786 will be issued upon authorization with 24-hour Dubai airside hold.";
        } else if (method === "crypto" && altTitle && altCopy) {
          altTitle.textContent = "USDC / BTC MULTI-SIG VAULT";
          altCopy.textContent =
            "Instant institutional rate lock generated on confirmation via Fireblocks Obsidian custody.";
        }
      }
    });
  });

  // Live sync of name & email to pass
  ["fullLegalNameInput", "privateEmailInput"].forEach((id) => {
    document.getElementById(id)?.addEventListener("input", updateTotalsAndPassCredentials);
  });

  // Form submit -> switch to Bespoke Itinerary Pass view
  const checkoutForm = document.getElementById("checkoutForm");
  if (checkoutForm) {
    checkoutForm.addEventListener("submit", (e) => {
      e.preventDefault();
      switchView("pass");
      showToast("Reservation authorized. Official Bespoke Itinerary Pass dispatched.");
    });
  }

  document.getElementById("returnToCheckoutBtn")?.addEventListener("click", () => {
    switchView("checkout");
  });

  document.getElementById("printPassBtn")?.addEventListener("click", () => {
    window.print();
  });

  document.getElementById("headerReserveBtn")?.addEventListener("click", () => {
    if (checkoutState.currentView === "pass") {
      switchView("checkout");
    } else {
      document.getElementById("authorizeBookingBtn")?.focus();
      showToast("Ready for authorization below.");
    }
  });
}

/* ==========================================================================
   18-PAGE NAVIGATOR MODAL & NAVIGATION
   ========================================================================== */
function openModal(modalId) {
  const modal = document.getElementById(modalId);
  if (modal) modal.hidden = false;
}

function closeModal(modalId) {
  const modal = document.getElementById(modalId);
