/* ==========================================================================
   HELPERS & RENDERING
   ========================================================================== */
function showToast(message) {
  const toast = document.getElementById("atelierToast");
  if (!toast) return;
  toast.textContent = message;
  toast.hidden = false;
  clearTimeout(showToast._timer);
  showToast._timer = setTimeout(() => {
    toast.hidden = true;
  }, 3000);
}

function renderFlagshipVisual(cityData) {
  if (cityData.imageUrl && cityData.imageUrl.trim() !== "") {
    return `<img class="flagship-photo-img" src="${cityData.imageUrl}" alt="${cityData.flagshipTitle}" />`;
  }

  return `
    <div class="flagship-image-placeholder" data-slot="${cityData.slot}">
      <svg class="globe-studio-svg" viewBox="0 0 80 80" fill="none" aria-hidden="true">
        <circle cx="40" cy="40" r="30" stroke="currentColor" stroke-width="1.3"/>
        <ellipse cx="40" cy="40" rx="14" ry="30" stroke="currentColor" stroke-width="1.1"/>
        <path d="M12 31H68M12 49H68M10 40H70" stroke="currentColor" stroke-width="1.1"/>
      </svg>
      <span class="placeholder-kicker">FLAGSHIP / CAR IMAGE PLACEHOLDER — ADD PHOTO</span>
      <span class="placeholder-slot-caption">${cityData.flagshipTitle} · ${cityData.slot}</span>
    </div>
  `;
}

function renderSelectedCity(cityKey) {
  const data = ATELIER_LOCATIONS[cityKey];
  if (!data) return;

  pageState.selectedCity = cityKey;

  document.querySelectorAll(".city-pill").forEach((pill) => {
    const isActive = pill.getAttribute("data-city") === cityKey;
    pill.classList.toggle("is-active", isActive);
    pill.setAttribute("aria-selected", String(isActive));
  });

  const stationed = document.getElementById("flagshipStationedPill");
  const title = document.getElementById("flagshipCityTitle");
  const address = document.getElementById("flagshipAddress");
  const tarmac = document.getElementById("flagshipTarmac");
  const hours = document.getElementById("flagshipHours");
  const ctaBtn = document.getElementById("browseCityFleetBtn");
  const visualSlot = document.getElementById("flagshipVisualSlot");

  if (stationed) stationed.textContent = data.stationedLabel;
  if (title) title.textContent = data.flagshipTitle;
  if (address) address.textContent = data.address;
  if (tarmac) tarmac.textContent = data.tarmac;
  if (hours) hours.textContent = data.hours;
  if (ctaBtn) ctaBtn.textContent = data.ctaLabel;
  if (visualSlot) visualSlot.innerHTML = renderFlagshipVisual(data);
}

function renderFaqs() {
  const stack = document.getElementById("faqStack");
  const empty = document.getElementById("faqEmptyState");
  if (!stack || !empty) return;

  const q = pageState.faqQuery.trim().toLowerCase();
  const filtered = CONCIERGE_FAQS.filter((item) => {
    if (!q) return true;
    return (
      item.question.toLowerCase().includes(q) ||
      item.answer.toLowerCase().includes(q) ||
      item.category.toLowerCase().includes(q)
    );
  });

  if (filtered.length === 0) {
    stack.innerHTML = "";
    empty.hidden = false;
    return;
  }

  empty.hidden = true;
  stack.innerHTML = filtered
    .map(
      (item) => `
      <article class="faq-card">
        <div class="faq-card-head">
          <h2 class="faq-question">${item.question}</h2>
          <span class="faq-category-tag">${item.category}</span>
        </div>
        <hr class="faq-divider" />
        <p class="faq-answer">${item.answer}</p>
      </article>
    `
    )
    .join("");
}

/* ==========================================================================
   PAGE 11 <-> PAGE 14 VIEW SWITCHING
   ========================================================================== */
function switchAtelierPage(pageNum) {
  const isFaq = pageNum === "14";
  pageState.activePage = isFaq ? "14" : "11";

  const locView = document.getElementById("locations-view");
  const faqView = document.getElementById("faq-view");
  const tab11 = document.getElementById("tabPage11");
  const tab14 = document.getElementById("tabPage14");
  const navLoc = document.getElementById("navLocationsLink");
  const navSvc = document.getElementById("navServicesLink");
  const badge = document.getElementById("activeModuleBadge");

  if (locView) locView.hidden = isFaq;
  if (faqView) faqView.hidden = !isFaq;

  if (tab11 && tab14) {
    tab11.classList.toggle("is-active", !isFaq);
    tab11.setAttribute("aria-selected", String(!isFaq));
    tab14.classList.toggle("is-active", isFaq);
    tab14.setAttribute("aria-selected", String(isFaq));
  }

  if (navLoc && navSvc) {
    navLoc.classList.toggle("is-active", !isFaq);
    navSvc.classList.toggle("is-active", isFaq);
  }

  if (badge) {
    badge.textContent = `${pageState.activePage}/18`;
  }

  renderNavigatorModules();
  window.scrollTo({ top: 0, behavior: "smooth" });
}

/* ==========================================================================
   18-PAGE NAVIGATOR MODAL & EVENTS
   ========================================================================== */
function openModal(modalId) {
  const modal = document.getElementById(modalId);
  if (modal) modal.hidden = false;
}

function closeModal(modalId) {
  const modal = document.getElementById(modalId);
  if (modal) modal.hidden = true;
}

function renderNavigatorModules() {
  const grid = document.getElementById("navigatorModuleGrid");
  if (!grid) return;

  grid.innerHTML = PROTOTYPE_MODULES.map(
    (mod) => `
      <button
        type="button"
        class="navigator-module-card ${mod.num === pageState.activePage ? "is-current" : ""}"
        data-select-module="${mod.num}"
      >
        <span class="module-num">MODULE ${mod.num}/18</span>
        <span class="module-name">${mod.title}</span>
      </button>
    `
  ).join("");
}

function setupInteractions() {
  // City selector pills
  document.querySelectorAll(".city-pill").forEach((pill) => {
    pill.addEventListener("click", () => {
      renderSelectedCity(pill.getAttribute("data-city"));
    });
  });

  // Page 11 / Page 14 switchers
  document.querySelectorAll("[data-switch-page]").forEach((el) => {
    el.addEventListener("click", (e) => {
      e.preventDefault();
      switchAtelierPage(el.getAttribute("data-switch-page"));
    });
  });

  // Live FAQ search
  const faqInput = document.getElementById("faqSearchInput");
  if (faqInput) {
    faqInput.addEventListener("input", (e) => {
      pageState.faqQuery = e.target.value;
      renderFaqs();
    });
  }

  document.getElementById("resetFaqSearchBtn")?.addEventListener("click", () => {
    pageState.faqQuery = "";
    if (faqInput) faqInput.value = "";
    renderFaqs();
  });

  // Navigator modal triggers
  ["openNavigatorTop", "floatingNavigatorBtn", "mobileNavigatorBtn"].forEach((id) => {
    document.getElementById(id)?.addEventListener("click", () => openModal("navigatorModal"));
  });

  document.getElementById("memberProfileBtn")?.addEventListener("click", () => {
    showToast("Alexander Vance · Obsidian Concierge Access Active");
  });

  document.querySelectorAll("[data-close-modal]").forEach((btn) => {
    btn.addEventListener("click", () => closeModal(btn.getAttribute("data-close-modal")));
  });

  document.querySelectorAll(".modal-backdrop").forEach((backdrop) => {
    backdrop.addEventListener("click", (e) => {
      if (e.target === backdrop) backdrop.hidden = true;
    });
  });

  document.addEventListener("click", (e) => {
    const modBtn = e.target.closest("[data-select-module]");
    if (modBtn) {
      const num = modBtn.getAttribute("data-select-module");
      const mod = PROTOTYPE_MODULES.find((m) => m.num === num);
      closeModal("navigatorModal");
      if (!mod) return;

      if (mod.page) {
        switchAtelierPage(mod.page);
        showToast(`Active Module ${mod.num}/18: ${mod.title}`);
      } else if (mod.href) {
        window.location.href = mod.href;
      }
    }
  });

  // Mobile menu toggle
  const mobileToggle = document.getElementById("mobileMenuToggle");
  const mobileDrawer = document.getElementById("mobileDrawer");
  if (mobileToggle && mobileDrawer) {
    mobileToggle.addEventListener("click", () => {
      const isHidden = mobileDrawer.hidden;
      mobileDrawer.hidden = !isHidden;
      mobileToggle.setAttribute("aria-expanded", String(isHidden));
    });
    mobileDrawer.querySelectorAll("a, button").forEach((item) => {
      item.addEventListener("click", () => {
        mobileDrawer.hidden = true;
        mobileToggle.setAttribute("aria-expanded", "false");
      });
    });
  }

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") closeModal("navigatorModal");
  });
}

/* ==========================================================================
   INITIALIZE
   ========================================================================== */
document.addEventListener("DOMContentLoaded", () => {
  renderSelectedCity("dubai");
  renderFaqs();
  renderNavigatorModules();
  setupInteractions();
});

