    </div>
  `;
}

/* ==========================================================================
   MEMBER SIGN IN & PRIVATE APPLICATION LOGIC
   ========================================================================== */
function updateSignedInUI(signedIn, email = "a.vance@obsidianholdings.ch") {
  portalState.isSignedIn = signedIn;

  const navLabel = document.getElementById("navMemberStatusLabel");
  const accessBtn = document.getElementById("accessVaultBtn");
  const statusBox = document.getElementById("vaultAccessStatus");
  const statusCopy = document.getElementById("vaultAccessCopy");

  if (signedIn) {
    if (navLabel) navLabel.textContent = "Alexander · Obsidian";
    if (accessBtn) accessBtn.textContent = "VAULT SESSION ACTIVE ✓";
    if (statusBox) statusBox.hidden = false;
    if (statusCopy) {
      statusCopy.textContent = `Authenticated as ${email}. Obsidian Tier zero-deposit privileges and 4-hour airside dispatch are unlocked.`;
    }
  } else {
    if (navLabel) navLabel.textContent = "Member Sign In";
    if (accessBtn) accessBtn.textContent = "ACCESS MEMBER VAULT";
    if (statusBox) statusBox.hidden = true;
  }
}

function setupPortalForms() {
  const signInForm = document.getElementById("memberSignInForm");
  const emailInput = document.getElementById("memberEmailInput");
  const passcodeInput = document.getElementById("memberPasscodeInput");
  const signOutBtn = document.getElementById("signOutBtn");

  if (signInForm) {
    signInForm.addEventListener("submit", (e) => {
      e.preventDefault();
      const email = emailInput?.value.trim() || "";
      const pass = passcodeInput?.value.trim() || "";
      if (!email || !pass) {
        showToast("Please enter both your member email and passcode.");
        return;
      }
      updateSignedInUI(true, email);
      showToast("Obsidian Member Vault unlocked.");
    });
  }

  if (signOutBtn) {
    signOutBtn.addEventListener("click", () => {
      updateSignedInUI(false);
      showToast("Signed out of Obsidian Member Vault.");
    });
  }

  const applyForm = document.getElementById("obsidianApplyForm");
  const applyName = document.getElementById("applyFullName");
  const applyEmail = document.getElementById("applyEmail");
  const applyPref = document.getElementById("applyPreference");
  const appBox = document.getElementById("applicationStatusBox");
  const appCopy = document.getElementById("applicationStatusCopy");

  if (applyForm) {
    applyForm.addEventListener("submit", (e) => {
      e.preventDefault();
      const name = applyName?.value.trim() || "";
      const email = applyEmail?.value.trim() || "";
      const pref = applyPref?.value || "Dubai";
      if (!name || !email) {
        showToast("Please complete your full name and corporate/family office email.");
        return;
      }

      if (appBox && appCopy) {
        appBox.hidden = false;
        appCopy.textContent = `Private invitation request received for ${name} (${email}) — ${pref}. Our Membership Director responds within 4 hours.`;
      }
      showToast(`Private application submitted for ${name}.`);
      applyForm.reset();
    });
  }

  document.getElementById("navMemberStatusBtn")?.addEventListener("click", () => {
    if (portalState.isSignedIn) {
      showToast("Alexander · Obsidian Session Active");
    } else {
      emailInput?.focus();
      showToast("Enter your credentials to access the Obsidian Member Vault.");
    }
  });
}

/* ==========================================================================
   18-PAGE NAVIGATOR MODAL & MOBILE MENU
   ========================================================================== */
function openModal(modalId) {
  const modal = document.getElementById(modalId);
  if (modal) modal.hidden = false;
}

function closeModal(modalId) {
  const modal = document.getElementById(modalId);
  if (modal) modal.hidden = true;
}

function renderNavigatorModules() {
  const grid = document.getElementById("navigatorModuleGrid");
  const badge = document.getElementById("activeModuleBadge");
  if (!grid) return;

  grid.innerHTML = PROTOTYPE_MODULES.map(
    (mod) => `
      <button
        type="button"
        class="navigator-module-card ${mod.num === portalState.activeModule ? "is-current" : ""}"
        data-select-module="${mod.num}"
      >
        <span class="module-num">MODULE ${mod.num}/18</span>
        <span class="module-name">${mod.title}</span>
      </button>
    `
  ).join("");

  if (badge) {
    badge.textContent = `${portalState.activeModule}/18`;
  }
}

function setupNavigatorAndDrawer() {
  renderNavigatorModules();

  ["openNavigatorTop", "floatingNavigatorBtn", "mobileNavigatorBtn"].forEach((id) => {
    document.getElementById(id)?.addEventListener("click", () => openModal("navigatorModal"));
  });

  document.querySelectorAll("[data-close-modal]").forEach((btn) => {
    btn.addEventListener("click", () => closeModal(btn.getAttribute("data-close-modal")));
  });

  document.querySelectorAll(".modal-backdrop").forEach((backdrop) => {
    backdrop.addEventListener("click", (e) => {
      if (e.target === backdrop) backdrop.hidden = true;
    });
  });

  document.addEventListener("click", (e) => {
    const modBtn = e.target.closest("[data-select-module]");
    if (modBtn) {
      const num = modBtn.getAttribute("data-select-module");
      const mod = PROTOTYPE_MODULES.find((m) => m.num === num);
      portalState.activeModule = num;
      renderNavigatorModules();
      closeModal("navigatorModal");
      if (!mod) return;

      if (mod.href.startsWith("#")) {
        document.querySelector(mod.href)?.scrollIntoView({ behavior: "smooth" });
        showToast(`Active Module ${mod.num}/18: ${mod.title}`);
      } else {
        window.location.href = mod.href;
      }
    }
  });

  const mobileToggle = document.getElementById("mobileMenuToggle");
  const mobileDrawer = document.getElementById("mobileDrawer");
  if (mobileToggle && mobileDrawer) {
    mobileToggle.addEventListener("click", () => {
      const isHidden = mobileDrawer.hidden;
      mobileDrawer.hidden = !isHidden;
      mobileToggle.setAttribute("aria-expanded", String(isHidden));
    });
    mobileDrawer.querySelectorAll("a, button").forEach((item) => {
      item.addEventListener("click", () => {
        mobileDrawer.hidden = true;
        mobileToggle.setAttribute("aria-expanded", "false");
      });
    });
  }

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") closeModal("navigatorModal");
  });
}

/* ==========================================================================
   INITIALIZE
   ========================================================================== */
document.addEventListener("DOMContentLoaded", () => {
  renderPortalVisualPlaceholder();
  setupPortalForms();
  setupNavigatorAndDrawer();
});
